CREATE TABLE public.consultation_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100), email text NOT NULL CHECK (char_length(email) <= 255), phone text NOT NULL CHECK (char_length(phone) BETWEEN 7 AND 20), constituency text NOT NULL CHECK (char_length(constituency) BETWEEN 1 AND 150), service text NOT NULL CHECK (char_length(service) <= 100), message text NOT NULL DEFAULT '' CHECK (char_length(message) <= 2000), consent boolean NOT NULL CHECK (consent = true), created_at timestamptz NOT NULL DEFAULT now()); GRANT INSERT ON public.consultation_requests TO anon, authenticated; GRANT ALL ON public.consultation_requests TO service_role; ALTER TABLE public.consultation_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public can request consultation" ON public.consultation_requests FOR INSERT TO anon, authenticated WITH CHECK (consent = true);